**JWT-based authentication flow:**

```python
from datetime import datetime, timedelta
import jwt
from fastapi import Depends, HTTPException
from fastapi.security import HTTPBearer, HTTPAuthorizationCredentials

SECRET = os.environ['JWT_SECRET']
ALGORITHM = 'HS256'

def create_token(user_id: int, expires_minutes: int = 15) -> str:
    payload = {
        'sub': str(user_id),
        'exp': datetime.utcnow() + timedelta(minutes=expires_minutes),
        'iat': datetime.utcnow(),
    }
    return jwt.encode(payload, SECRET, algorithm=ALGORITHM)

def create_refresh_token(user_id: int) -> str:
    return create_token(user_id, expires_minutes=60 * 24 * 7)  # 7 days

security = HTTPBearer()

async def get_current_user(
    credentials: HTTPAuthorizationCredentials = Depends(security),
) -> int:
    try:
        payload = jwt.decode(credentials.credentials, SECRET, algorithms=[ALGORITHM])
        return int(payload['sub'])
    except jwt.ExpiredSignatureError:
        raise HTTPException(401, 'Token expired')
    except jwt.InvalidTokenError:
        raise HTTPException(401, 'Invalid token')

# Login endpoint
@app.post('/auth/login')
async def login(email: str, password: str):
    user = await verify_credentials(email, password)
    if not user:
        raise HTTPException(401, 'Invalid credentials')
    return {
        'access_token': create_token(user.id),
        'refresh_token': create_refresh_token(user.id),
    }

# Protected endpoint
@app.get('/api/profile')
async def profile(user_id: int = Depends(get_current_user)):
    return await get_user(user_id)
```

**Security considerations:**
- Short-lived access tokens (15 min) + long-lived refresh tokens (7 days)
- Store refresh tokens in httpOnly cookies (not localStorage)
- Rotate refresh tokens on use (detect stolen tokens)
- Keep the JWT secret truly secret (env var, not in code)

Flask's default errors are HTML because it was built for web apps. You need to override them for an API. Here's the pattern:

**1. Register JSON error handlers:**
```python
@app.errorhandler(404)
def not_found(e):
    return {'error': 'Resource not found'}, 404

@app.errorhandler(400)
def bad_request(e):
    return {'error': str(e.description)}, 400

@app.errorhandler(500)
def server_error(e):
    app.logger.exception('Unhandled error')  # Log the traceback!
    return {'error': 'Internal server error'}, 500
```

**2. Create a custom API exception:**
```python
class APIError(Exception):
    def __init__(self, message, status_code=400):
        self.message = message
        self.status_code = status_code

@app.errorhandler(APIError)
def handle_api_error(e):
    return {'error': e.message}, e.status_code
```

**3. Use it in routes:**
```python
@bp.get('/users/<int:user_id>')
def get_user(user_id):
    user = User.query.get(user_id)
    if not user:
        raise APIError('User not found', 404)
    return user.to_dict()
```

The key insight: always log 500s with full tracebacks (so you can debug), but never expose internal details to the client. The client gets a clean JSON error; your logs get the full story.

function useSearch(query) {
  const [results, setResults] = useState([]);

  useEffect(() => {
    const controller = new AbortController();

    const timer = setTimeout(async () => {
      try {
        const res = await fetch(
          `/api/search?q=${encodeURIComponent(query)}`,
          { signal: controller.signal }
        );
        const data = await res.json();

        if (!controller.signal.aborted) {
          setResults(data);
        }
      } catch (error) {
        if (error.name !== "AbortError") {
          console.error("Search request failed:", error);
        }
      }
    }, 300);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query]);

  return results;
}

Stare continuously at the **`O`** in the exact center for 15 to 30 seconds without blinking or moving your eyes. 

As you stare, the high-contrast checker-patterns and inverted slashes in your peripheral vision will begin to **vibrate, shift, or pulse inward and outward**, making the flat text look like a breathing 3D tunnel.

```text
\\\\\\\\\\\\\\\\\\\\\\\\////////////////////////
\\\\\\\\\\\\\\\\\\\\\\    //////////////////////
\\\\\\\\\\\\\\\\\\\\  # #   ////////////////////
\\\\\\\\\\\\\\\\\\  # @ @ #   //////////////////
\\\\\\\\\\\\\\\\  # @ . . @ #   ////////////////
\\\\\\\\\\\\\\  # @ . : : . @ #   //////////////
\\\\\\\\\\\\  # @ . : + + : . @ #   ////////////
\\\\\\\\\\  # # . : +     + : . # #   //////////
\\\\\\\\    # @ . : + (O) + : . @ #    /////////
//////////  # # . : +     + : . # #   \\\\\\\\\\
////////////  # @ . : + + : . @ #   \\\\\\\\\\\\
//////////////  # @ . : : . @ #   \\\\\\\\\\\\\\
////////////////  # @ . . @ #   \\\\\\\\\\\\\\\\
////////////////''  # @ @ #   ''\\\\\\\\\\\\\\\\
////////////////////  # #   \\\\\\\\\\\\\\\\\\\\
//////////////////////    \\\\\\\\\\\\\\\\\\\\\\
////////////////////////\\\\\\\\\\\\\\\\\\\\\\\\
```

### Why this works:
1. **Peripheral Drift:** The outer quadrants swap directional slashes (`\\\\` vs `////`). Your peripheral vision struggles to process these opposing high-frequency angles while your fovea (center vision) is locked onto the `(O)`.
2. **Contrast Fatigue:** The alternating light (`.`), medium (`@`, `:`), and dark (`#`) concentric rings fatigue the photoreceptors in your eyes, creating an illusory sensation of movement or depth ("tunnel effect").

