```javascript
// async/await — use try/catch
async function fetchUser(id) {
  try {
    const res = await fetch(`/api/users/${id}`);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (error) {
    if (error.name === 'AbortError') {
      console.log('Request was cancelled');
    } else {
      console.error('Failed to fetch user:', error.message);
      throw error; // Re-throw if you can't handle it
    }
  }
}

// Promise chains — use .catch()
fetch('/api/data')
  .then(res => res.json())
  .then(data => process(data))
  .catch(err => console.error('Pipeline failed:', err));

// Global unhandled rejections (last resort)
window.addEventListener('unhandledrejection', (event) => {
  console.error('Unhandled promise rejection:', event.reason);
  event.preventDefault(); // Prevent default browser logging
});
```

Always handle errors at the right level. Don't catch if you can't do anything useful — let it bubble up to a centralized error handler.

