Memoization is the top-down approach to dynamic programming: solve problems recursively, but cache results to avoid redundant computation. Instead of recalculating `fib(5)` every time it's needed, store the result after the first computation.

```python
@lru_cache(maxsize=None)
def fib(n):
    if n < 2: return n
    return fib(n-1) + fib(n-2)
# fib(100) is instant — each value computed once
```

The bottom-up alternative (tabulation) builds a table iteratively from base cases. Both achieve the same complexity but memoization is more intuitive while tabulation often uses less memory.

```python
class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.is_end = True

    def search(self, word: str) -> bool:
        node = self._find(word)
        return node is not None and node.is_end

    def starts_with(self, prefix: str) -> bool:
        return self._find(prefix) is not None

    def words_with_prefix(self, prefix: str) -> list[str]:
        node = self._find(prefix)
        results = []
        if node:
            self._collect(node, prefix, results)
        return results

    def _find(self, s: str) -> TrieNode | None:
        node = self.root
        for ch in s:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

    def _collect(self, node, path, results):
        if node.is_end:
            results.append(path)
        for ch, child in node.children.items():
            self._collect(child, path + ch, results)
```

Usage:

```python
t = Trie()
for w in ["car", "card", "care", "cat", "dog"]:
    t.insert(w)

print(t.search("car"))            # True
print(t.search("ca"))             # False
print(t.starts_with("ca"))        # True
print(t.words_with_prefix("car")) # ['car', 'card', 'care']
```

**Complexity:** insert/search/starts_with are O(L) for word length L; `words_with_prefix` is O(L + total chars in matched words).

```python
class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str):
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_end = True

    def search(self, word: str) -> bool:
        node = self._find(word)
        return node is not None and node.is_end

    def starts_with(self, prefix: str) -> bool:
        return self._find(prefix) is not None

    def _find(self, prefix: str):
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node
```

O(m) per operation where m is the word/prefix length. Used for autocomplete, spell checking, IP routing.

